// Shared YAML value types used by both the parser and the dumper.
//
// safe_load converts YAML timestamp scalars into datetime objects, and the
// dumper emits them back in plain (unquoted) form. To round-trip that
// behavior we wrap the original scalar text in this marker class.

export class YamlTimestamp {
  constructor(text) {
    this.text = text;
  }
}

