const fakeArgv = ['/usr/bin/node', '/output/test4.mjs', ...process.argv.slice(2)];
const result = parseArgs(fakeArgv);
// Print the parsed value in a way the harness can compare (the real program
// would YAML-dump it; here we only check argparse behavior).
process.stdout.write('A=' + result.a + '\n');
